static double motion(unsigned q,double rate,double *amp){ApoScratchStretch*v=calloc(1,sizeof(*v));double e=0,c=0,s=0;for(int i=0;i<24000;i++){double cursor=48000+rate*i;float y=r9_render(v,pcm,96000,48000,48000,cursor,rate,1,q);if(!isfinite(y))exit(2);if(i>=12000){e+=y*y;c+=y*cos(2*3.141592653589793*220*i/48000);s+=y*sin(2*3.141592653589793*220*i/48000);}}*amp=2*hypot(c,s)/12000;free(v);return sqrt(e/12000);}
